import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 510;
    static int n_value, m_value, mod_value;
    static int[][] binom = new int[MAX_SIZE][MAX_SIZE];
    static PairType[][] dp_array = new PairType[MAX_SIZE][MAX_SIZE];

    static class PairType {
        int first, second;

        PairType(int first, int second) {
            this.first = first;
            this.second = second;
        }

        PairType add(PairType other) {
            return new PairType(addModulo(this.first, other.first), addModulo(this.second, other.second));
        }

        PairType multiply(PairType other) {
            long firstPart = (1L * this.first * other.first) % mod_value;
            long secondPart = (1L * this.first * other.second + 1L * this.second * other.first) % mod_value;
            return new PairType((int) firstPart, (int) secondPart);
        }
    }

    static int sumInterval(int start, int end) {
        return (start + end) * (end - start + 1) / 2;
    }

    static int addModulo(int a, int b) {
        int sum = a + b;
        if (sum >= mod_value) sum -= mod_value;
        return sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n_value = sc.nextInt();
        m_value = sc.nextInt();
        mod_value = sc.nextInt();

        for (int i = 0; i < MAX_SIZE; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = addModulo(binom[i - 1][j], binom[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= n_value; i++) {
            for (int j = 0; j <= m_value; j++) {
                dp_array[i][j] = new PairType(0, 0);
            }
        }

        for (int i = 0; i <= n_value; i++) {
            dp_array[i][0] = new PairType(1, 0);
            for (int j = 1; j <= i && j <= m_value; j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        PairType term = dp_array[k - 1][k - 1].multiply(dp_array[i - k][j - k + 1])
                                .multiply(new PairType(binom[j][k - 1], 0));
                        dp_array[i][j] = dp_array[i][j].add(term);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        PairType t1 = dp_array[k - 1][k - 1];
                        PairType t2 = dp_array[i - k][i - k];
                        PairType comb = new PairType(binom[i - 1][k - 1], 0);
                        int factor = i + 1 - sumInterval(1, k) + sumInterval(k + 1, i) - k * (i - k);
                        PairType factor_pair = new PairType(factor, 0);
                        PairType product = t1.multiply(t2).multiply(comb).multiply(factor_pair);
                        dp_array[i][j] = dp_array[i][j].add(product);
                    }
                }
            }
        }
        System.out.println(dp_array[n_value][m_value].second);
        sc.close();
    }
}

